// Polish catalogue. `Partial` like every non-source catalogue: anything not
// translated yet falls back to English at lookup time.
//
// Polish uses the same four CLDR categories as Russian but draws the lines
// differently: `few` covers 2 to 4, `many` covers 0 and 5 upwards, and both
// recur for larger numbers (22 takes `few`, 25 takes `many`). Every plural
// entry here authors all four forms.

