  "settings.game.cacheSizeAlert.disabled": "Wyłączone",
  "settings.game.cacheRollingBranches": "Przechowuj gałęzie deweloperskie w pamięci podręcznej (FAF Develop i Beta)",
  "settings.game.cacheRollingBranchesHint": "Zachowuje każdą rozegraną wersję develop i beta, by ich powtórki nadal działały.",
  "settings.game.experimentalBadge": "Eksperymentalne",
  "settings.game.cacheRollingBranchesDocTitle": "Jak działa buforowanie gałęzi deweloperskich i obsługa powtórek",
  "settings.game.cacheRollingBranchesDocOverview": "Gałęzie ciągłe, takie jak FAF Develop i FAF Beta, nie mają stałych numerów wersji na serwerze. Gdy pojawiają się nowe commity, stare pliki są nadpisywane, co powoduje desynchronizację starych powtórek.",
  "settings.game.cacheRollingBranchesDocHowTitle": "Tworzenie migawek wersji",
  "settings.game.cacheRollingBranchesDocHowDesc": "Po włączeniu każda unikalna wersja jest oznaczana skrótem SHA commita Git i sumą kontrolną plików, a następnie zapisywana w lokalnym manifeście.",
  "settings.game.cacheRollingBranchesDocReplayTitle": "Zmiany w plikach powtórek",
  "settings.game.cacheRollingBranchesDocReplayDesc": "Lokalnie zapisywane pliki .fafreplay zawierają pola git_sha, git_short_sha oraz build_signature w nagłówku JSON. Pozwala to klientowi odtworzyć dokładnie tę samą wersję podczas odtwarzania powtórki, zachowując pełną zgodność z innymi klientami FAF.",
  "settings.game.cacheRollingBranchesDocStorageTitle": "Efektywność pamięci masowej",
  "settings.game.cacheRollingBranchesDocStorageDesc": "Pliki są łączone za pomocą twardych dowiązań bez powielania miejsca na dysku. Możesz je przeglądać lub usuwać na liście poniżej.",
