  "settings.connectivity.hostAdapter": "Hostowanie przez",
  "settings.connectivity.hostAdapterHint": "Hostowanie z Go dodaje [go-adapter] do tytułu gry: gracze w trybie Dynamiczny w tym kliencie dołączą wtedy z Go sami, pozostali muszą przełączyć się na Go. Działa od następnej gry.",
