  "settings.discord.disallowJoinsVia": "Zablokuj dołączanie przez Discord",
  "settings.discord.disallowJoinsViaHint": "Zachowaj widoczny status, ale usuń przycisk dołączania, aby nikt nie wszedł do twojej poczekalni z Discorda.",
  "settings.steam.presence": "Status Steam",
  "settings.steam.presenceHint": "W trakcie gry Steam pokazuje, że grasz w Forged Alliance, i liczy godziny; otwarty klient się nie liczy. Wymaga uruchomionego Steama i Forged Alliance w bibliotece. Wyłączone, dopóki tego nie włączysz.",
  "settings.steam.confirmButton": "Włącz",
  "settings.steam.confirmTitle": "Włączyć status Steam?",
  "settings.steam.confirmBody": "Podczas gry klient załaduje bibliotekę Steamworks Valve o zamkniętym kodzie. Mówi ona Steamowi, kiedy grasz w Forged Alliance na FAF, a my nie możemy sprawdzić, co jeszcze biblioteka mogłaby wysyłać do Valve.",
  "settings.steam.trustClosed": "Do tego klient musi załadować bibliotekę Steamworks Valve, która ma zamknięty kod. Wybieramy, które jej funkcje wywołujemy, i wywołujemy tylko trzy (start, podtrzymanie, zamknięcie), ale nie możemy zobaczyć ani sprawdzić, co sama biblioteka robi lub wysyła do Valve. Włączając to, ufasz w tym Valve.",
  "settings.steam.trustCalls": "Sam klient mówi Steamowi tylko, że zacząłeś i skończyłeś grać w Forged Alliance. Steam wie wtedy, które konto grało i od kiedy do kiedy, i pokazuje to znajomym zgodnie z Twoimi ustawieniami prywatności Steam. FAF to osobny klient: bez tego Steam nie wie, kiedy grasz na FAF.",
  "settings.steam.trustTitle": "Co to wysyła i czego nie możemy sprawdzić",
