  "tournaments.playoffs.helpBottom": "Każdy bez porażki wybiera po kolei przeciwnika spośród graczy z {lowest}. Resztę łączy się według rozstawienia, najlepszy z pozostałych z najsłabszym. Rozstawienie wynika z tabeli, potem z sumy punktów pokonanych rywali.",
