  "tournaments.console.directorNote": "Jako dyrektor turniejów masz całą konsolę poza Administratorami: prośby o dostęp, dyrektorów, bany, logi, zarchiwizowane turnieje i artykuły FAQ / Zasad.",
  "tournaments.console.offTitle": "Uprawnienia wyłączone",
  "tournaments.console.offHint": "Jesteś administratorem, ale wyłączyłeś uprawnienia, więc widzisz stronę jak zwykły gracz, łącznie z pulami map. Włącz je, aby używać konsoli.",
  "tournaments.console.switchOn": "Włącz ponownie uprawnienia administratora",
  "tournaments.console.tabRequests": { one: "Prośby ({count} czeka)", few: "Prośby ({count} czekają)", many: "Prośby ({count} czeka)", other: "Prośby ({count} czeka)" },
  "tournaments.console.tabSiteAdmins": "Administratorzy ({count})",
