  "tournaments.console.tabArticles": "Artykuły",
  "tournaments.console.siteAdminsHint": "Administratorzy mają pełną kontrolę nad turniejami i konsolą. Dostęp jest powiązany z kontem FAF: łączy się je hasłem głównym, które zawsze połączy ponownie, nawet po usunięciu tutaj. Dodaj innych po nazwie FAF poniżej.",
  "tournaments.console.siteAdminsNone": "Brak połączonych administratorów.",
  "tournaments.console.makeSiteAdmin": "Uczyń administratorem",
  "tournaments.console.removeSelfAdmin": "Usunąć własny dostęp administratora? Możesz połączyć się ponownie hasłem.",
  "tournaments.console.removeAdmin": "Usunąć tego administratora?",
  "tournaments.console.directorsTitle": "Globalni dyrektorzy turniejów ({count})",
  "tournaments.console.directorsHint": "Dyrektorzy mają prawa organizatora we wszystkich oficjalnych turniejach (nie społecznościowych), widzą szkice wszystkich (bez praw w społecznościowych) i mają w konsoli prośby, dyrektorów, bany, logi, archiwum i artykuły.",
  "tournaments.console.directorsHint2": "Dyrektorzy mogą dodawać i usuwać dyrektorów, więc zespół zarządza sobą sam. Każda zmiana jest logowana z nazwiskiem autora, a ostatniego dyrektora nie da się usunąć.",
  "tournaments.console.directorsNone": "Brak dyrektorów.",
  "tournaments.console.makeDirector": "Uczyń dyrektorem",
  "tournaments.console.removeSelfDirector": "Usunąć siebie jako dyrektora? Stracisz prawa we wszystkich oficjalnych turniejach i konsolę. Przywrócić może tylko administrator.",
  "tournaments.console.removeDirector": "Usunąć tego dyrektora? Straci dostęp do wszystkich oficjalnych turniejów.",
  "tournaments.console.bansTitle": "Globalne bany",
  "tournaments.console.bansHint": "Zbanowane konta nie mogą się zapisać, zostać dodane ani zaproszone do oficjalnych turniejów (społecznościowe bez zmian). Najszerszy zakres: organizatorzy banują w turnieju, właściciele serii w serii. Datę można zmienić w każdej chwili, a wygasły ban przestaje działać, zachowując wpis.",
